function rolCtrl($http,$scope,_commonSvc,form,apiUrl,decodeToken){$scope.maxSize=5,$scope.totalRecords=0,$scope.pageIndex=1,$scope.pageSize=10,$scope.recordsQuantity=[5,10,25,50];let idUsuarioRol,jsonParams={idRol:parseInt(decodeToken.idUsuarioRol)};$scope.getRoles=()=>{showLoader(),$http.get(`${apiUrl.admin}api/Rol/Get/${JSON.stringify(jsonParams)}`).then(({data:response})=>{hideLoader(),"0"!==response.id?$scope.roles=JSON.parse(response.data)||[]:toastr.warning(response.message,response.titleSms)}).catch(error=>{hideLoader();const msg=error.config?error.config.url:error;toastr.error(msg)})},$scope.getRoles()}app.controller("rolCtrl",rolCtrl),rolCtrl.$inject=["$http","$scope","commonService","formulario","apiUrl","decodeToken"];